1	<!DOCTYPE html>
2	<html lang="zh-TW">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>大樹教練 AI 特助心法 — 一鍵注入任何 AI</title>
7	<meta name="description" content="大樹教練 26 年企業培訓淬煉的 AI 協作方法論。一鍵複製，貼給任何 AI（Claude / ChatGPT / Gemini / Grok），30 秒內進入頂級特助狀態。">
8	<meta property="og:title" content="大樹教練 AI 特助心法 — 一鍵注入任何 AI">
9	<meta property="og:description" content="老闆動嘴，AI 全自動執行。21 條特助守則，跨平台一鍵注入。">
10	<meta property="og:type" content="website">
11	<meta property="og:url" content="https://coach1973.github.io/ai-go/">
12	<style>
13	@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;600;700;800;900&display=swap');
14	
15	:root {
16	  --bg: #FFFBF5;
17	  --bg-warm: #FFF8EC;
18	  --bg-deep: #FFF3DC;
19	  --surface: #FFFFFF;
20	  --border: #F0E4D0;
21	  --border-strong: #E0D0B0;
22	  --primary: #D4692A;        /* 主橘 */
23	  --primary-dark: #A84820;
24	  --green: #4A8B70;          /* 大樹綠 */
25	  --green-dark: #2F6B52;
26	  --text: #3D2B1F;
27	  --text-dim: #7A6A5A;
28	  --text-muted: #A89880;
29	  --shadow-sm: 0 2px 8px rgba(61,43,31,0.06);
30	  --shadow-md: 0 8px 24px rgba(61,43,31,0.12);
31	  --shadow-lg: 0 16px 48px rgba(61,43,31,0.18);
32	}
33	
34	* { box-sizing: border-box; margin: 0; padding: 0; }
35	html { scroll-behavior: smooth; }
36	body {
37	  background: var(--bg);
38	  color: var(--text);
39	  font-family: 'Noto Sans TC', 'Microsoft JhengHei UI', -apple-system, sans-serif;
40	  line-height: 1.8;
41	  font-size: 17px;
42	  font-weight: 500;
43	  -webkit-font-smoothing: antialiased;
44	}
45	
46	.container {
47	  max-width: 980px;
48	  margin: 0 auto;
49	  padding: 0 24px;
50	}
51	
52	/* === HERO === */
53	.hero {
54	  background: linear-gradient(180deg, var(--bg-deep) 0%, var(--bg-warm) 100%);
55	  padding: 80px 0 64px;
56	  border-bottom: 1px solid var(--border);
57	  text-align: center;
58	}
59	.hero-eyebrow {
60	  display: inline-block;
61	  padding: 6px 16px;
62	  background: rgba(74,139,112,0.12);
63	  color: var(--green-dark);
64	  border-radius: 999px;
65	  font-size: 14px;
66	  font-weight: 700;
67	  letter-spacing: 0.5px;
68	  margin-bottom: 24px;
69	}
70	.hero h1 {
71	  font-size: clamp(32px, 5vw, 52px);
72	  font-weight: 900;
73	  line-height: 1.25;
74	  color: var(--text);
75	  margin-bottom: 20px;
76	}
77	.hero h1 .accent { color: var(--primary); }
78	.hero-sub {
79	  font-size: clamp(17px, 2vw, 22px);
80	  color: var(--text-dim);
81	  font-weight: 600;
82	  max-width: 720px;
83	  margin: 0 auto 48px;
84	  line-height: 1.7;
85	}
86	.hero-sub strong { color: var(--primary-dark); font-weight: 800; }
87	
88	/* === 三句話核心 === */
89	.creed {
90	  display: grid;
91	  grid-template-columns: repeat(3, 1fr);
92	  gap: 20px;
93	  max-width: 800px;
94	  margin: 0 auto 56px;
95	}
96	.creed-card {
97	  background: var(--surface);
98	  border: 1px solid var(--border);
99	  border-radius: 16px;
100	  padding: 24px 18px;
101	  box-shadow: var(--shadow-sm);
102	  transition: transform 0.2s;
103	}
104	.creed-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
105	.creed-label {
106	  font-size: 13px;
107	  font-weight: 700;
108	  color: var(--green-dark);
109	  letter-spacing: 1px;
110	  margin-bottom: 8px;
111	}
112	.creed-text {
113	  font-size: 16px;
114	  font-weight: 700;
115	  color: var(--text);
116	  line-height: 1.5;
117	}
118	@media (max-width: 640px) {
119	  .creed { grid-template-columns: 1fr; }
120	}
121	
122	/* === 一鍵複製按鈕（核心 UX）=== */
123	.copy-zone {
124	  background: var(--surface);
125	  border: 2px solid var(--primary);
126	  border-radius: 24px;
127	  padding: 40px 32px;
128	  max-width: 720px;
129	  margin: 0 auto;
130	  box-shadow: var(--shadow-lg);
131	  position: relative;
132	}
133	.copy-zone-label {
134	  font-size: 14px;
135	  font-weight: 800;
136	  color: var(--primary-dark);
137	  letter-spacing: 1.5px;
138	  margin-bottom: 12px;
139	}
140	.copy-zone-title {
141	  font-size: clamp(22px, 3vw, 28px);
142	  font-weight: 800;
143	  color: var(--text);
144	  margin-bottom: 8px;
145	}
146	.copy-zone-hint {
147	  font-size: 15px;
148	  color: var(--text-dim);
149	  margin-bottom: 28px;
150	}
151	.btn-copy {
152	  display: inline-flex;
153	  align-items: center;
154	  justify-content: center;
155	  gap: 10px;
156	  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
157	  color: #fff;
158	  font-size: 18px;
159	  font-weight: 800;
160	  padding: 18px 40px;
161	  border: none;
162	  border-radius: 999px;
163	  cursor: pointer;
164	  box-shadow: 0 8px 24px rgba(212,105,42,0.4);
165	  transition: all 0.2s;
166	  font-family: inherit;
167	  letter-spacing: 0.5px;
168	  min-width: 280px;
169	}
170	.btn-copy:hover { transform: translateY(-2px); box-shadow: 0 12px 32px rgba(212,105,42,0.55); }
171	.btn-copy:active { transform: translateY(0); }
172	.btn-copy.copied {
173	  background: linear-gradient(135deg, var(--green) 0%, var(--green-dark) 100%);
174	  box-shadow: 0 8px 24px rgba(74,139,112,0.4);
175	}
176	.btn-icon { font-size: 22px; }
177	
178	.url-zone {
179	  margin-top: 24px;
180	  padding-top: 24px;
181	  border-top: 1px dashed var(--border-strong);
182	  font-size: 14px;
183	  color: var(--text-dim);
184	}
185	.url-code {
186	  display: inline-block;
187	  background: var(--bg-deep);
188	  border: 1px solid var(--border);
189	  border-radius: 8px;
190	  padding: 6px 12px;
191	  font-family: 'SF Mono', Menlo, monospace;
192	  font-size: 13px;
193	  color: var(--primary-dark);
194	  font-weight: 700;
195	  margin-top: 6px;
196	  cursor: pointer;
197	  transition: background 0.2s;
198	}
199	.url-code:hover { background: var(--bg-warm); }
200	
201	/* === 怎麼用 3 步驟 === */
202	.section {
203	  padding: 80px 0;
204	}
205	.section h2 {
206	  font-size: clamp(26px, 4vw, 36px);
207	  font-weight: 900;
208	  text-align: center;
209	  margin-bottom: 16px;
210	  color: var(--text);
211	}
212	.section-sub {
213	  text-align: center;
214	  color: var(--text-dim);
215	  font-size: 17px;
216	  margin-bottom: 48px;
217	  max-width: 600px;
218	  margin-left: auto;
219	  margin-right: auto;
220	}
221	
222	.steps {
223	  display: grid;
224	  grid-template-columns: repeat(3, 1fr);
225	  gap: 24px;
226	}
227	.step {
228	  background: var(--surface);
229	  border: 1px solid var(--border);
230	  border-radius: 20px;
231	  padding: 32px 24px;
232	  box-shadow: var(--shadow-sm);
233	  position: relative;
234	}
235	.step-num {
236	  position: absolute;
237	  top: -20px;
238	  left: 24px;
239	  width: 44px;
240	  height: 44px;
241	  border-radius: 50%;
242	  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
243	  color: #fff;
244	  display: flex;
245	  align-items: center;
246	  justify-content: center;
247	  font-weight: 900;
248	  font-size: 20px;
249	  box-shadow: var(--shadow-md);
250	}
251	.step h3 {
252	  font-size: 19px;
253	  font-weight: 800;
254	  margin: 12px 0 12px;
255	  color: var(--text);
256	}
257	.step p {
258	  color: var(--text-dim);
259	  font-size: 15px;
260	  line-height: 1.7;
261	}
262	@media (max-width: 768px) {
263	  .steps { grid-template-columns: 1fr; }
264	}
265	
266	/* === 跨平台 === */
267	.platforms-section {
268	  background: var(--bg-warm);
269	  border-top: 1px solid var(--border);
270	  border-bottom: 1px solid var(--border);
271	}
272	.platforms {
273	  display: flex;
274	  flex-wrap: wrap;
275	  justify-content: center;
276	  gap: 16px;
277	  max-width: 800px;
278	  margin: 0 auto;
279	}
280	.platform {
281	  display: inline-flex;
282	  align-items: center;
283	  gap: 10px;
284	  background: var(--surface);
285	  border: 1px solid var(--border);
286	  border-radius: 999px;
287	  padding: 12px 22px;
288	  font-weight: 700;
289	  font-size: 15px;
290	  color: var(--text);
291	  box-shadow: var(--shadow-sm);
292	}
293	.platform-dot {
294	  width: 10px;
