645	<script>
646	const PROMPT_URL = 'system-prompt.md';
647	let promptCache = null;
648	
649	async function loadPrompt() {
650	  if (promptCache) return promptCache;
651	  const res = await fetch(PROMPT_URL);
652	  if (!res.ok) throw new Error('載入失敗：' + res.status);
653	  promptCache = await res.text();
654	  return promptCache;
655	}
656	
657	// 跨源 iframe fallback（Chrome 對 clipboard API 在跨源 iframe 有限制，需 focused frame）
658	function fallbackCopy(text) {
659	  const ta = document.createElement('textarea');
660	  ta.value = text;
661	  ta.style.position = 'fixed';
662	  ta.style.top = '0';
663	  ta.style.left = '0';
664	  ta.style.opacity = '0';
665	  ta.style.pointerEvents = 'none';
666	  document.body.appendChild(ta);
667	  ta.focus();
668	  ta.select();
669	  const ok = document.execCommand('copy');
670	  document.body.removeChild(ta);
671	  if (!ok) throw new Error('execCommand copy failed');
672	}
673	
674	async function copyPrompt() {
675	  const btn = document.getElementById('copyBtn');
676	  const btnText = document.getElementById('copyBtnText');
677	  const original = btnText.textContent;
678	  try {
679	    const text = await loadPrompt();
680	    // 優先用 Clipboard API（同源 / focused frame 時最佳）
681	    await navigator.clipboard.writeText(text);
682	    btn.classList.add('copied');
683	    btnText.textContent = '✅ 已複製！貼給 AI 即可';
684	    showToast('✅ 已複製到剪貼簿，貼給 AI 即可');
685	    setTimeout(() => {
686	      btn.classList.remove('copied');
687	      btnText.textContent = original;
688	    }, 3500);
689	  } catch (e) {
690	    // Clipboard API 失敗（跨源 iframe / 權限被拒）→ 降級到 execCommand
691	    try {
692	      const text = await loadPrompt();
693	      fallbackCopy(text);
694	      btn.classList.add('copied');
695	      btnText.textContent = '✅ 已複製（相容模式）！貼給 AI 即可';
696	      showToast('✅ 已複製到剪貼簿（相容模式）');
697	      setTimeout(() => {
698	        btn.classList.remove('copied');
699	        btnText.textContent = original;
700	      }, 3500);
701	    } catch (e2) {
702	      // 兩個方法都失敗 → 提示用戶手動複製
703	      btnText.textContent = '⚠️ 複製失敗，請用 Cmd+A 全選後 Cmd+C';
704	      showToast('⚠️ 自動複製失敗，請手動選取複製');
705	      console.error('Both clipboard methods failed:', e, e2);
706	    }
707	  }
708	}
