730	    showToast('✅ 教練人設已複製到剪貼簿');
731	    setTimeout(() => {
732	      btn.classList.remove('copied');
733	      btnText.textContent = original;
734	    }, 3500);
735	  } catch (e) {
736	    try {
737	      const text = await loadPersona();
738	      fallbackCopy(text);
739	      btn.classList.add('copied');
740	      btnText.textContent = '✅ 已複製（相容模式）！';
741	      showToast('✅ 教練人設已複製（相容模式）');
742	      setTimeout(() => {
743	        btn.classList.remove('copied');
744	        btnText.textContent = original;
745	      }, 3500);
746	    } catch (e2) {
747	      btnText.textContent = '⚠️ 複製失敗，請用 Cmd+A 全選後 Cmd+C';
748	      showToast('⚠️ 自動複製失敗，請手動選取複製');
749	      console.error('Both persona clipboard methods failed:', e, e2);
750	    }
751	  }
752	}
753	
754	async function copyUrl() {
755	  try {
756	    await navigator.clipboard.writeText('https://coach1973.github.io/ai-go/');
757	    showToast('✅ 網址已複製');
758	  } catch (e) {
759	    // 降級：execCommand
760	    try {
761	      fallbackCopy('https://coach1973.github.io/ai-go/');
762	      showToast('✅ 網址已複製（相容模式）');
763	    } catch (e2) {
764	      console.error('copyUrl failed:', e, e2);
765	      showToast('⚠️ 複製失敗，請手動選取網址');
766	    }
767	  }
768	}
769	
770	function showToast(msg) {
771	  const t = document.getElementById('toast');
